CREATE TABLE [dbo].[RepAgentSession](	  [date] DATETIME NOT NULL	, [login] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [userId] INT NOT NULL	, [user] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [extension] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [loginTime] DATETIME NOT NULL	, [logoutTime] DATETIME NOT NULL	, [sessionTime] INT NOT NULL	, [sessionTimeSeconds] INT NOT NULL	, [year] INT NOT NULL	, [month] INT NOT NULL	, [day] INT NOT NULL	, [hour] INT NOT NULL	, [minutes] INT NOT NULL)CREATE NONCLUSTERED INDEX [IX_RepAgentSession] ON [dbo].[RepAgentSession] ([date] ASC)